mapper.select:
select from sys_menu where delete_flag = 1 and status = 1 and platform in
#{platform}
order by order_num asc, id asc

select 
from sys_menu
where delete_flag = 1
  and status = 1
  and (
    platform = 2
    or (
      platform = 0
      and id in (
          select tm.menu_id
          from sys_tenant_menu tm
          where tm.delete_flag = 1
            and tm.tenant_id = #{tenantId}
      )
      and id in (
          select rm.menu_id
          from sys_role_menu rm
          join sys_role r on r.id = rm.role_id and r.delete_flag = 1 and r.status = 1
          join sys_role_user ru on ru.role_id = r.id and ru.delete_flag = 1 and ru.tenant_id = #{tenantId}
          where rm.delete_flag = 1
            and ru.user_id = #{userId}
            and r.tenant_id = #{tenantId}
      )
    )
  )
order by order_num asc, id asc

select count(1)
from sys_menu
where delete_flag = 1 and parent_code = #{parentCode}
